mapper.select:
select

    d.location,d.model_code,d.longitude,d.latitude,d.height,d.model_code,

c.device_code, c.channel_code
from vm_order_devices c

    left join vm_device_labels_rel dlr on dlr.tenant_id = c.tenant_id and dlr.device_code = c.device_code
    left join vm_tenant_label_config tlc on tlc.label_id = dlr.label_id


    left join vm_organ_device_rel_t odr on odr.tenant_id = c.tenant_id and odr.device_code = c.device_code and odr.delete_flag = '0'


    left join vm_device_info_t d on c.device_code = d.device_code

where c.tenant_id = #{param.tenantId}

    and tlc.label_id = #{param.deviceLabelId,jdbcType=CHAR}


    and tlc.label_id in

        #{item}



    and odr.dept_id = #{param.orgId,jdbcType=CHAR}


    and odr.dept_id in

        #{item}



    and d.model_code = #{param.modelId,jdbcType=CHAR}


    and d.model_code in

        #{item}




    and (c.device_name like CONCAT('%', #{param.deviceName}, '%') or d.device_name like CONCAT('%', #{param.deviceName}, '%'))

select DISTINCT su.user_id, su.dept_id, su.user_name, su.user_type, su.nick_name, su.email, su.avatar, su.phonenumber,su.telephone as telPhone, su.sex, su.status, su.del_flag, su.login_ip, su.login_date, su.create_by, su.remark, su.login_fail_num, su.enterprise_id, su.tenant_id, su.is_tenant_admin, sd.dept_name from sys_user su left join sys_dept sd on su.dept_id = sd.dept_id WHERE su.del_flag = '0' and su.STATUS = '0'
AND su.user_id in
#{item}

SELECT a.latitude, a.longitude, a.location, a.province_id, a.city_id, a.county_id, a.height, a.model_code AS modelId, p.area_name AS provinceName, ci.area_name AS cityName, co.area_name AS countyName, a.alarm_location, t.focus_range as focusRange, t.verti_down_neg as vertiDownNeg, a.device_name FROM vm_device_info_t a left join vm_device_model_t t on a.device_model_code = t.device_model_code and a.model_code = t.mfgr_code LEFT JOIN sys_area p ON a.province_id = p.area_code LEFT JOIN sys_area ci ON a.city_id = ci.area_code LEFT JOIN sys_area co ON a.county_id = co.area_code WHERE a.delete_flag = '0' and a.device_code in
#{deviceCode}
LIMIT 1

SELECT a.latitude, a.longitude, a.location, a.province_id, a.city_id, a.county_id, a.height, a.model_code AS modelId, a.device_code, a.device_name, a.device_model_code AS deviceModelCode, p.area_name AS provinceName, ci.area_name AS cityName, co.area_name AS countyName FROM vm_iot_device_t a left join vm_iot_device_model_t t on a.device_model_code = t.device_model_code and a.model_code = t.mfgr_code LEFT JOIN sys_area p ON a.province_id = p.area_code LEFT JOIN sys_area ci ON a.city_id = ci.area_code LEFT JOIN sys_area co ON a.county_id = co.area_code WHERE a.delete_flag = '0' and a.device_code in
#{deviceCode}
LIMIT 1

SELECT preset_id AS presetId, preset_name AS presetName FROM vm_video_preset WHERE preset_id in
#{presetId}
AND device_code in
#{item}
ORDER BY update_time DESC

select b.device_code as deviceCode,b.device_name as deviceName,b.channel_code as channelCode,b.channel_name as channelName,b.tenant_id as tenantId
from vm_tenant_device_channel_rel_t b
where b.delete_flag = '0'

    AND b.device_code = #{deviceCode}


    AND b.tenant_id = #{tenantId}


    AND b.channel_code = #{channelCode}



    AND b.device_code in

        #{item}



    AND b.channel_code in

        #{item}

SELECT preset_id,preset_name,device_code FROM vm_video_preset WHERE delete_flag = 0 AND (device_code,preset_id) in (
(#{param.deviceCode},#{param.presetId})
)

SELECT dev.channel_code, ( CASE WHEN length( IFNULL( t.channel_name, '' )) = 0 THEN dev.channel_name ELSE t.channel_name END ) AS channelName FROM vm_channel_info_t dev LEFT JOIN ( SELECT DISTINCT tdr.device_code, tdr.channel_code, tdr.channel_name FROM vm_tenant_device_channel_rel_t tdr WHERE ( tdr.device_code, tdr.channel_code, tdr.tenant_id, tdr.industry_code ) IN (
(#{param.deviceCode},#{param.channelCode},#{param.tenantId},#{param.industryCode})
) ) t ON t.device_code = dev.device_code AND t.channel_code = dev.channel_code WHERE dev.delete_flag = '0' AND ( dev.device_code, dev.channel_code ) IN (
(#{param.deviceCode},#{param.channelCode})
)
